import { useEffect, useState, useRef } from 'react'
import {
  View,
  Text,
  Button,
  ToastAndroid,
  Platform,
  StyleSheet,
  ActivityIndicator,
} from 'react-native'
import he from 'he'
import PropTypes from 'prop-types'
import * as Animatable from 'react-native-animatable'

const QuizComponent = ({ refreshing, category, numQuestions }) => {
  const [questions, setQuestions] = useState([])
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0)
  const [score, setScore] = useState(0)
  const [rightOrWrong, setRightOrWrong] = useState('')
  const [loading, setLoading] = useState(false)
  const [quizCompleted, setQuizCompleted] = useState(false)
  const previousQuestions = useRef(new Set())

  const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

  const fetchQuestions = async (retryCount = 0) => {
    console.log('Category:', category)
    setLoading(true)
    try {
      const response = await fetch(
        `https://opentdb.com/api.php?amount=${numQuestions}&category=${category}&type=boolean`
      )
      const data = await response.json()
      console.log('API Response:', data)

      if (data.response_code === 0 && data.results.length > 0) {
        const newQuestions = data.results.filter(
          (question) => !previousQuestions.current.has(question.question)
        )
        if (newQuestions.length > 0) {
          setQuestions(newQuestions)
          newQuestions.forEach((question) =>
            previousQuestions.current.add(question.question)
          )
        } else {
          console.log('Duplicate questions found, fetching new ones...')
          await delay(5000)
          fetchQuestions()
        }
      } else if (data.response_code === 5) {
        if (retryCount < 3) {
          console.log('Rate limit hit, waiting for 5 seconds...')
          await delay(5000)
          fetchQuestions(retryCount + 1)
        } else {
          console.log('Rate limit hit, maximum retries reached.')
        }
      } else {
        console.log('No questions found or other error')
      }
    } catch (error) {
      console.error('Failed to fetch questions:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleAnswer = async (selectedAnswer, correctAnswer) => {
    if (selectedAnswer === correctAnswer) {
      setScore((prevScore) => prevScore + 1)
      if (Platform.OS === 'android') {
        ToastAndroid.show('Correct!', ToastAndroid.SHORT)
      } else {
        setRightOrWrong('Correct!')
        setTimeout(() => {
          setRightOrWrong('')
        }, 1500)
      }
    } else {
      if (Platform.OS === 'android') {
        ToastAndroid.show('Incorrect!', ToastAndroid.SHORT)
      } else {
        setRightOrWrong('Incorrect!')
        setTimeout(() => {
          setRightOrWrong('')
        }, 1500)
      }
    }

    if (currentQuestionIndex < questions.length - 1) {
      setCurrentQuestionIndex((prevIndex) => prevIndex + 1)
    } else {
      setQuizCompleted('Quiz Completed!')
    }
  }

  useEffect(() => {
    if (questions.length === 0) {
      fetchQuestions()
    }
  }, [refreshing])

  return (
    <View style={styles.container}>
      {loading ? (
        <>
          <ActivityIndicator size='large' color='#00ff00' />
          <Text style={styles.question}>The API is taking time</Text>
        </>
      ) : quizCompleted === 'Quiz Completed!' ? (
        <View>
          <Text style={styles.question}>Quiz Completed!</Text>
          <Text style={styles.score}>
            Final Score: {score}/{questions.length}
          </Text>
        </View>
      ) : (
        questions.length > 0 && (
          <>
            <View key={questions[currentQuestionIndex].question}>
              <Text style={styles.questionNumber}>
                Question {currentQuestionIndex + 1}
              </Text>
              <Animatable.Text animation='bounceIn' style={styles.question}>
                {he.decode(questions[currentQuestionIndex].question)}
              </Animatable.Text>

              <Button
                title='True'
                onPress={() =>
                  handleAnswer(
                    'True',
                    questions[currentQuestionIndex].correct_answer
                  )
                }
              />
              <Button
                title='False'
                onPress={() =>
                  handleAnswer(
                    'False',
                    questions[currentQuestionIndex].correct_answer
                  )
                }
              />
            </View>
            <View style={styles.scoreContainer}>
              <Text style={styles.score}>
                Score: {score}/{questions.length}
              </Text>
            </View>
          </>
        )
      )}

      <Text>
        {rightOrWrong && (
          <Animatable.Text style={styles.question} animation='fadeIn'>
            {rightOrWrong}
          </Animatable.Text>
        )}
      </Text>
    </View>
  )
}

QuizComponent.propTypes = {
  refreshing: PropTypes.bool.isRequired,
  category: PropTypes.string.isRequired,
  numQuestions: PropTypes.string.isRequired,
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
  },
  question: {
    color: 'white',
    marginBottom: 10,
    textAlign: 'center',
  },
  questionNumber: {
    color: 'white',
    marginBottom: 10,
    textAlign: 'center',
    fontSize: 18,
  },
  score: {
    color: 'white',
    fontSize: 24,
    fontWeight: 'bold',
  },
  scoreContainer: {
    position: 'absolute',
    top: 250,
    width: 150,
  },
})

export default QuizComponent
